        class Tuple : Comparable<Tuple> {
            var a: Int
            var b: Int
            var c: Int

            constructor(a: Int, b: Int) {
                this.a = a
                this.b = b
                c = 0
            }

            constructor(a: Int, b: Int, c: Int) {
                this.a = a
                this.b = b
                this.c = c
            }

            fun getA(): Int {
                return a
            }

            fun getB(): Int {
                return b
            }

            fun getC(): Int {
                return c
            }

            override fun compareTo(other: Tuple): Int {
                if (a == other.a) {
                    return if (b == other.b) java.lang.Long.compare(c.toLong(), other.c.toLong()) else java.lang.Long.compare(
                        b.toLong(),
                        other.b.toLong()
                    )
                }
                return java.lang.Long.compare(a.toLong(), other.a.toLong())
            }

            override fun hashCode(): Int {
                return Arrays.deepHashCode(arrayOf(a, b, c))
            }

            override fun equals(o: Any?): Boolean {
                if (o !is Tuple) return false
                val pairo = o
                return a == pairo.a && b == pairo.b && c == pairo.c
            }

            override fun toString(): String {
                return String.format("(%d %d %d)  ", a, b, c)
            }
        }

