        class FastScanner @Throws(FileNotFoundException::class)
        constructor(filename: String) {
            private var sin: InputStream = FileInputStream(File(filename))
            private val buffer = ByteArray(1024)
            private var ptr = 0
            private var buflen = 0

            constructor() : this(System.`in`) {}

            private constructor(inputStream: InputStream) {
                sin = inputStream
            }

            private fun hasNextByte(): Boolean {
                if (ptr < buflen) {
                    return true
                } else {
                    ptr = 0
                    try {
                        buflen = sin.read(buffer)
                    } catch (e: IOException) {
                        e.printStackTrace()
                    }
                    if (buflen <= 0) {
                        return false
                    }
                }
                return true
            }

            private fun readByte(): Int {
                return if (hasNextByte()) buffer[ptr++].toInt() else -1
            }

            private fun isPrintableChar(c: Int): Boolean {
                return c in 33..126
            }

            fun hasNext(): Boolean {
                while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
                return hasNextByte()
            }

            fun next(): String {
                if (!hasNext()) throw NoSuchElementException()
                val sb = StringBuilder()
                var b = readByte()
                while (isPrintableChar(b)) {
                    sb.appendCodePoint(b)
                    b = readByte()
                }
                return sb.toString()
            }

            fun longNext(): Long {
                if (!hasNext()) throw NoSuchElementException()
                var n: Long = 0
                var minus = false
                var b = readByte()
                if (b == '-'.code) {
                    minus = true
                    b = readByte()
                }
                if (b < '0'.code || '9'.code < b) {
                    throw NumberFormatException()
                }
                while (true) {
                    if ('0'.code <= b && b <= '9'.code) {
                        n *= 10
                        n += (b - '0'.code).toLong()
                    } else if (b == -1 || !isPrintableChar(b) || b == ':'.code) {
                        return if (minus) -n else n
                    } else {
                        throw NumberFormatException()
                    }
                    b = readByte()
                }
            }

            fun intNext(): Int {
                val nl = longNext()
                if (nl < Int.MIN_VALUE || nl > Int.MAX_VALUE) throw NumberFormatException()
                return nl.toInt()
            }

            fun doubleNext(): Double {
                return next().toDouble()
            }

            fun nextLongArray(n: Int): LongArray {
                val a = LongArray(n)
                for (i in 0 until n) a[i] = longNext()
                return a
            }

            fun nextIntArray(n: Int): IntArray {
                val a = IntArray(n)
                for (i in 0 until n) a[i] = intNext()
                return a
            }

            fun nextDoubleArray(n: Int): DoubleArray {
                val a = DoubleArray(n)
                for (i in 0 until n) a[i] = doubleNext()
                return a
            }

            fun getAdj(n: Int): Array<ArrayList<Int>?> {
                val adj = arrayOfNulls<ArrayList<Int>>(n + 1)
                for (i in 1..n) adj[i] = ArrayList()
                return adj
            }

            @Throws(IOException::class)
            fun adjacencyList(nodes: Int, edges: Int): Array<ArrayList<Int>?> {
                return adjacencyList(nodes, edges, false)
            }

            @Throws(IOException::class)
            fun adjacencyList(nodes: Int, edges: Int, isDirected: Boolean): Array<ArrayList<Int>?> {
                adj = getAdj(nodes)
                for (i in 0 until edges) {
                    val a = intNext()
                    val b = intNext()
                    adj!![a]!!.add(b)
                    if (!isDirected) adj!![b]!!.add(a)
                }
                return adj!!
            }
        }

