                val lp = IntArray(n + 1)
                val pr = ArrayList<Int>()
                var i = 2
                while (i <= n) {
                    if (lp[i] == 0) {
                        lp[i] = i
                        pr.add(i)
                    }
                    var j = 0
                    while (j < pr.size && pr[j] <= lp[i] && i * pr[j] <= n) {
                        lp[i * pr[j]] = pr[j]
                        j++
                    }
                    i++
                }
                return pr
