                var rVar = r
                var nVar = n
                if (rVar > nVar - rVar) rVar = nVar - rVar
                var ans: Long = 1
                var i = 1
                while (i <= rVar) {
                    ans *= nVar.toLong()
                    ans /= i.toLong()
                    nVar--
                    i++
                }
                return ans
            }

