    @Throws(IOException::class)
    fun solver() {
        n = `in`.intNext()
        m = `in`.intNext()
        arr = `in`.nextIntArray(n)
        required = sum(*arr)
        typeDays = HashMap()
        for (i in 0 until m) {
            val d = `in`.intNext()
            val typ = `in`.intNext()
            if (arr[typ - 1] <= 0) continue
            if (!typeDays.containsKey(typ)) typeDays[typ] = TreeSet()
            typeDays[typ]!!.add(d)
        }
        var lo = required
        var hi = 2 * required
        var valid = hi
        while (lo <= hi) {
            val mid = (lo + hi) / 2
            if (isEnough(mid)) {
                valid = mid
                hi = mid - 1
            } else lo = mid + 1
        }
        out.println(valid)
    }

    fun isEnough(day: Int): Boolean {
        var totalCoin = day
        var req = required
        val ddays = IntArray(day + 1)
        for (typ in typeDays.keys) {
            val lastDay = typeDays[typ]!!.floor(day)
            if (lastDay == null) continue
            ddays[lastDay] += arr[typ - 1]
        }
        var removed = 0
        for (i in 1..day) {
            val coins = i - removed
            val toRemove = min(coins, ddays[i])
            removed += toRemove
            totalCoin -= toRemove
            req -= toRemove
        }
        return req * 2 <= totalCoin
    }

